dtsPropsFor.Button:
/** Visual style. */
  variant?: 'primary' | 'secondary';
  /** Height and padding preset. */
  size?: 'sm' | 'md';
  className?: string;
  children?: React.ReactNode;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  /** Also accepts all standard <button> attributes. A ButtonLink export with the same variant/size renders a Next.js link. */

dtsPropsFor.Card:
className?: string;
  children?: React.ReactNode;
  /** Also accepts standard <div> attributes. Compose with CardTitle (as h2 or h3) and CardText for the heading and body text. */

dtsPropsFor.Container:
/** Max-width preset. */
  size?: 'default' | 'narrow';
  className?: string;
  children?: React.ReactNode;
  /** Also accepts all standard <div> attributes. */

dtsPropsFor.Section:
/** Background treatment. `panel` adds a subtle banded surface; defaults to `plain`. */
  surface?: 'plain' | 'panel';
  className?: string;
  children?: React.ReactNode;
  /** Also accepts all standard <section> attributes. Compose with Container and SectionHeading for headed content. */

dtsPropsFor.SectionHeading:
eyebrow?: string;
  title?: string;
  description?: string;
  className?: string;

dtsPropsFor.CheckList:
/** List entries, each rendered with the standard check marker. */
  items: readonly string[];
  className?: string;

dtsPropsFor.PageHero:
/** Small label above the page title. */
  eyebrow: string;
  /** Page heading. */
  title: string;
  /** Supporting paragraph under the heading. */
  description: string;

dtsPropsFor.ClosingCta:
/** Heading. Defaults to "Start with a free workflow review." */
  title?: string;
  /** Reassurance line under the heading. Defaults to the site response commitment. */
  reassurance?: string;
